    /// v42.0.0 (CIRISPersist#814 part 4, CC 4.5.5) — **the directional
    /// sub-scope table, spelled as LITERALS.**
    ///
    /// Deliberately not derived from `delegation_scope::*`: a table generated
    /// from the constants under test cannot fail when the constants are the
    /// thing that is wrong, and the vector this exists to pin
    /// (`infra:attest:licensure:acme` must NOT satisfy `infra:attest`) is a
    /// relation between two strings, not a property of either.
    #[test]
    fn scope_covers_is_directional_and_boundary_exact_814() {
        for (held, wanted, expect, why) in [
            ("infra:attest", "infra:attest", true, "exact"),
            (
                "infra:attest",
                "infra:attest:licensure:acme",
                true,
                "a parent covers its child — this is what attenuation MEANS",
            ),
            (
                "infra:attest:licensure:acme",
                "infra:attest",
                false,
                "THE HAZARD: a child must never widen to its parent. \
                 `held.starts_with(wanted)` returns true here and hands a \
                 deliberately narrowed holder the full attest capability",
            ),
            (
                "infra:attest:licensure:acme",
                "infra:attest:licensure:other",
                false,
                "siblings cover nothing",
            ),
            (
                "infra:attest",
                "infra:attest_assurance",
                false,
                "the COLON BOUNDARY: v30.2.0 split these two authorities on \
                 purpose; a bare prefix test silently re-merges them",
            ),
            (
                "infra:attest",
                "infra:attestation",
                false,
                "colon boundary again — a string prefix is not a sub-scope",
            ),
            (
                "infra:attest:licensure:acme",
                "infra:attest:licensure:acme",
                true,
                "an exact caveat is still exact",
            ),
            (
                "moderate",
                "moderate",
                true,
                "the unprefixed duty ladder is unaffected by this cut",
            ),
            (
                "moderate",
                "moderate:something",
                true,
                "the relation is not infra-specific; it is about the token shape",
            ),
            ("infra:attest", "", false, "empty is covered by nothing"),
            ("", "infra:attest", false, "empty covers nothing"),
            (
                "infra:attest",
                "infra:attest:",
                false,
                "a trailing-colon caveat is EMPTY — fail closed rather than \
                 treat it as the parent",
            ),
        ] {
            assert_eq!(
                scope_covers(held, wanted),
                expect,
                "scope_covers({held:?}, {wanted:?}) should be {expect} — {why}"
            );
        }
    }

    /// **I2964 (v62, CC rc21 CC 3.1; CLM-scope-attenuation)** — a key caveat
    /// is written with the key's bare segment (one `:`-segment, no colon of
    /// its own), and `scope_covers` stays DIRECTIONAL over it: the root and
    /// the parent cover the caveat, the caveat covers its sub-caveat and
    /// itself; the caveat never covers its parent; another key's caveat is
    /// not covered, nor is a caveat on a prefix of the segment; and the
    /// relation is antisymmetric over all of them.
    #[test]
    fn i2964_scope_covers_is_directional_over_a_key_segment() {
        use crate::federation::namespace::key_segment::tests::segment;
        let (a, b) = (segment('Q'), segment('g'));
        let parent = "infra:attest:licensure";
        let caveat_a = format!("{parent}:{a}");
        let caveat_b = format!("{parent}:{b}");
        let sub_a = format!("{caveat_a}:board");
        let cut_a = format!("{parent}:{}", &a[..20]);
        // CC rc21: a URN (or other non-segment) in the key position matches
        // no key: the caveat grants nothing beyond itself.
        let urn_caveat = format!(
            "{parent}:{}",
            crate::federation::namespace::key_segment::tests::kid('Q')
        );
        for (held, wanted, expect, why) in [
            (
                "infra:attest",
                caveat_a.as_str(),
                true,
                "the root covers the caveat",
            ),
            (
                parent,
                caveat_a.as_str(),
                true,
                "the parent covers the caveat",
            ),
            (
                caveat_a.as_str(),
                caveat_a.as_str(),
                true,
                "a caveat covers itself",
            ),
            (
                caveat_a.as_str(),
                sub_a.as_str(),
                true,
                "the caveat covers its sub-caveat",
            ),
            (
                caveat_a.as_str(),
                parent,
                false,
                "a child never covers its parent",
            ),
            (caveat_a.as_str(), "infra:attest", false, "nor the root"),
            (
                sub_a.as_str(),
                caveat_a.as_str(),
                false,
                "nor its own parent caveat",
            ),
            (
                caveat_a.as_str(),
                caveat_b.as_str(),
                false,
                "another key's caveat",
            ),
            (
                cut_a.as_str(),
                caveat_a.as_str(),
                false,
                "a prefix of the segment",
            ),
            (
                cut_a.as_str(),
                sub_a.as_str(),
                false,
                "a prefix of the segment, deeper",
            ),
            (
                urn_caveat.as_str(),
                caveat_a.as_str(),
                false,
                "a URN caveat grants no key's caveat",
            ),
            (
                urn_caveat.as_str(),
                sub_a.as_str(),
                false,
                "nor its sub-caveat",
            ),
            (urn_caveat.as_str(), parent, false, "nor its parent"),
        ] {
            assert_eq!(
                scope_covers(held, wanted),
                expect,
                "I2964: scope_covers({held:?}, {wanted:?}) — {why}"
            );
        }
        let tokens = [
            "infra:attest".to_owned(),
            parent.to_owned(),
            caveat_a.clone(),
            caveat_b,
            sub_a,
            cut_a,
        ];
        for x in &tokens {
            for y in &tokens {
                if x != y && scope_covers(x, y) {
                    assert!(
                        !scope_covers(y, x),
                        "I2964: {x:?} and {y:?} cover each other"
                    );
                }
            }
        }
    }

    /// v42.0.0 (CIRISPersist#814 part 4) — the relation is ANTISYMMETRIC on
    /// distinct tokens: if `a` covers `b` and they differ, `b` must not cover
    /// `a`. Stated as a property because the failure mode is a symmetric
    /// implementation (`starts_with` in either argument order), which no
    /// single row of the table above catches on its own.
    #[test]
    fn scope_covers_is_antisymmetric_814() {
        let tokens = [
            "infra:attest",
            "infra:attest:licensure:acme",
            "infra:attest:licensure:other",
            "infra:attest_assurance",
            "infra:serve",
            "moderate",
        ];
        for a in tokens {
            for b in tokens {
                if a != b && scope_covers(a, b) {
                    assert!(
                        !scope_covers(b, a),
                        "{a:?} covers {b:?} AND {b:?} covers {a:?} — the relation \
                         is symmetric, which means a child can widen to its parent"
                    );
                }
            }
        }
    }
    use super::*;

